'use strict';
const $=s=>document.querySelector(s),KEY='courtboard-v1',display=new URLSearchParams(location.search).get('display'),uid=()=>crypto.randomUUID(),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const newGame=(a,b,mode='5')=>({id:uid(),a,b,mode,minutes:10,periods:mode==='3'?1:4,otMinutes:5,period:1,score:[0,0],fouls:[0,0],timeouts:[0,0],pos:0,clock:600000,shot:mode==='3'?12000:24000,running:false,shotRunning:false,stamp:Date.now(),status:'대기',history:[],quarters:[]});
let screenMode='single',menuOpen=false;try{screenMode=localStorage.getItem('courtboard-screen-mode')==='dual'?'dual':'single'}catch{}
function applyScreenMode(){if(display)return;document.body.className=screenMode==='single'?'single'+(menuOpen?' menu-open':''):'';$('#screenMode').value=screenMode;$('#cornerMenu').textContent=menuOpen?'× 전광판으로':'⚙ 메뉴';$('#cornerMenu').setAttribute('aria-expanded',String(menuOpen));}
$('#screenMode').onchange=e=>{screenMode=e.target.value;menuOpen=false;try{localStorage.setItem('courtboard-screen-mode',screenMode)}catch{}applyScreenMode();e.target.blur()};
$('#cornerMenu').onclick=()=>{menuOpen=!menuOpen;applyScreenMode();$('#cornerMenu').blur()};
let db;try{db=JSON.parse(localStorage.getItem(KEY))}catch{}if(!db?.tournaments?.length){const g=newGame('HOME','AWAY');db={tournaments:[{id:uid(),name:'우리 동호회 대회',games:[g]}],selected:null,game:g.id};db.selected=db.tournaments[0].id}
let tour=()=>db.tournaments.find(t=>t.id===db.selected)||db.tournaments[0],game=()=>tour().games.find(g=>g.id===db.game),channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('courtboard'):null,audio,modalSubmit;
const remaining=(g,field,now=Date.now())=>Math.max(0,g[field]-((field==='clock'?g.running:g.shotRunning)?now-g.stamp:0));
function materialize(g){const now=Date.now();g.clock=remaining(g,'clock',now);g.shot=remaining(g,'shot',now);g.stamp=now}
function persist(){if(display)return;try{localStorage.setItem(KEY,JSON.stringify(db));$('#saveState').textContent='● 기기에 저장됨'}catch{$('#saveState').textContent='저장 실패 · 백업 필요'}channel?.postMessage(db)}
function mutate(fn,history=true){if(display)return;let g=game();if(!g||g.status==='종료')return;materialize(g);if(history){const copy={...g};delete copy.history;g.history.push(JSON.parse(JSON.stringify(copy)));if(g.history.length>80)g.history.shift()}fn(g);persist();render()}
const voices=new Map();let audioReady=false;
async function unlock(){if(display)return false;try{if(navigator.audioSession)navigator.audioSession.type='playback';audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state!=='running')await audio.resume();audioReady=audio.state==='running';return audioReady}catch{return false}}
function stopBuzzer(kind){const v=voices.get(kind);if(!v)return;v.cancelled=true;if(v.timer)clearTimeout(v.timer);try{v.osc?.stop();v.osc?.disconnect();v.gain?.disconnect()}catch{}voices.delete(kind)}
async function beep(kind='game',duration=3000){stopBuzzer(kind);const v={cancelled:false};voices.set(kind,v);if(!await unlock()||v.cancelled){if(voices.get(kind)===v)voices.delete(kind);return}const o=audio.createOscillator(),gain=audio.createGain();v.osc=o;v.gain=gain;o.type='sawtooth';o.frequency.value=kind==='shot'?880:220;gain.gain.value=.25;o.connect(gain);gain.connect(audio.destination);o.start();if(duration!==null){o.stop(audio.currentTime+duration/1000);v.timer=setTimeout(()=>{if(voices.get(kind)===v)stopBuzzer(kind)},duration)}}
if(!display){document.addEventListener('pointerdown',()=>{unlock()},{passive:true});document.addEventListener('keydown',()=>{unlock()});document.addEventListener('keyup',e=>{if(e.code==='KeyH')stopBuzzer('manual')});window.addEventListener('blur',()=>stopBuzzer('manual'));document.addEventListener('visibilitychange',()=>{if(document.hidden)stopBuzzer('manual')})}
$('#audioTest').onclick=async()=>{const ready=await unlock();$('#audioTest').textContent=ready?'♪ 낮은 버저 확인 중':'소리 활성화 실패 · 다시 탭';if(ready)beep('game')};
function timeoutGroup(g){return g.mode==='3'?'3x3':g.period>g.periods?'ot'+(g.period-g.periods):g.period<=2?'first':'second'}
function timeoutLimit(g){return g.mode==='3'||g.period>g.periods?1:g.period<=2?2:3}
function timeoutDots(g,i){return `<div class="timeoutdots" role="img" aria-label="타임아웃 ${timeoutLimit(g)}회 중 ${g.timeouts[i]}회 사용">${Array.from({length:timeoutLimit(g)},(_,n)=>`<span class="timeoutdot ${n<g.timeouts[i]?'used':''}"></span>`).join('')}</div>`}
function syncTimeouts(g){const key=timeoutGroup(g);g.timeoutLedger??={};if(!g.timeoutLedger[key])g.timeoutLedger[key]=g.timeoutGroup===undefined?g.timeouts.map(n=>Math.min(timeoutLimit(g),Math.max(0,Math.floor(n)))):[0,0];g.timeoutGroup=key;g.timeouts=[...g.timeoutLedger[key]]}
function shotTime(ms){return ms<=10000?(ms/1000).toFixed(1):String(Math.ceil(ms/1000))}
function time(ms){const seconds=Math.ceil(ms/1000);if(ms<60000)return (ms/1000).toFixed(1);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function board(){const g=game();if(g)syncTimeouts(g);if(!g){$('#board').innerHTML='<div class="status">등록된 경기가 없습니다. 경기 등록으로 시작하세요.</div>';return}const p=g.period>g.periods?`OT ${g.period-g.periods}`:g.mode==='3'?'3 × 3':`${g.period} QUARTER`;$('#board').innerHTML=`<div class="boardtop">${esc(tour().name)} · ${g.mode==='3'?'3 × 3':'5 × 5'}</div><div class="scores">${team(g,0)}<div class="clockblock"><div class="period">${p}</div><div class="digits time" id="clockvalue">${g.mode==='3'&&g.period>g.periods?'--:--':time(remaining(g,'clock'))}</div><div class="label">GAME TIME</div><div class="possession centerpos" aria-label="${g.pos===1?'왼쪽 공격권':g.pos===2?'오른쪽 공격권':'공격권 미지정'}">${g.pos===1?'◀':g.pos===2?'▶':''}</div><div class="digits shot" id="shotvalue">${shotTime(remaining(g,'shot'))}</div></div>${team(g,1)}</div>`}
function team(g,i){return `<div class="team"><div class="teamname">${esc(i?g.b:g.a)}</div><div class="digits points">${String(g.score[i]).padStart(2,'0')}</div>${timeoutDots(g,i)}<div class="teamstats"><div><span class="label">TEAM FOULS</span><strong>${g.fouls[i]}</strong></div></div></div>`}
const shortcutLabels={'toggle':'O','shot':'E','reset':'W','14':'Q','adjust:clock:60000':'U','adjust:clock:-60000':'J','adjust:clock:1000':'I','adjust:clock:-1000':'K','adjust:shot:1000':'R','adjust:shot:-1000':'F','score:0:1':'A','score:0:2':'S','score:0:3':'D','score:0:-1':'Z','score:1:1':"'",'score:1:2':';','score:1:3':'L','score:1:-1':'/','foul:0:1':'X','foul:1:1':'.','timeout:0':'C','timeout:1':',','period':'N'};
const btn=(label,action,cls='')=>`<button type="button" data-act="${action}" class="${cls}"><span>${label}</span>${shortcutLabels[action]?`<kbd>${esc(shortcutLabels[action])}</kbd>`:''}</button>`;
function render(){board();if(display)return;$('#tournaments').innerHTML=db.tournaments.map(t=>`<option value="${esc(t.id)}" ${t.id===tour().id?'selected':''}>${esc(t.name)}</option>`).join('');$('#gameCount').textContent=`${tour().games.length} GAMES`;$('#games').innerHTML=tour().games.map((g,i)=>`<button data-game="${esc(g.id)}" class="${g.id===db.game?'active':''}"><small>GAME ${String(i+1).padStart(2,'0')} · ${g.status} · ${g.mode==='3'?'3×3':'5×5'}</small><strong>${esc(g.a)} <span class="sub">vs</span> ${esc(g.b)}</strong>${g.status!=='대기'?`<em>${g.score[0]} : ${g.score[1]}</em>`:''}</button>`).join('');const g=game();$('#matchTitle').textContent=g?`${g.a} vs ${g.b}`:'경기를 등록하세요';if(!g){$('#controls').innerHTML='';return}$('#controls').innerHTML=`<div class="controlgrid">${teamControls(g,0)}<div class="panel clockpanel"><h3>시간 조작</h3><div class="clockgroup"><div class="grouptitle">경기시간</div><div class="buttons">${btn(g.running?'Ⅱ 경기 정지':'▶ 경기 시작','toggle','primary')}</div><div class="stepper"><div class="buttons">${btn('+1분','adjust:clock:60000')}${btn('−1분','adjust:clock:-60000')}</div><div class="buttons">${btn('+1초','adjust:clock:1000')}${btn('−1초','adjust:clock:-1000')}</div></div></div><div class="clockgroup"><div class="grouptitle">샷클락</div><div class="buttons">${btn(g.shotRunning?'Ⅱ 샷 정지':'▶ 샷 시작','shot')}</div><div class="buttons">${btn(g.mode==='3'?'12초 ↺':'24초 ↺','reset')}${g.mode==='5'?btn('14초 ↺','14'):''}</div><div class="buttons">${btn('+1초','adjust:shot:1000')}${btn('−1초','adjust:shot:-1000')}</div></div><div class="buttons">${btn('시간 수정','editTime')}${btn('버저 ♪','buzzer')}</div><div class="sub">두 시계는 각각 독립적으로 작동합니다.</div></div>${teamControls(g,1)}</div><div class="bottomcontrols">${btn('↶ 직전 조작 취소','undo')}${btn('공격권 전환 ⇄','pos')}${btn('다음 쿼터 / 연장','period')}${btn(g.status==='종료'?'결과 수정 재개':'경기 종료 · 결과 저장',g.status==='종료'?'reopen':'finish','danger')}</div>`;if(g.status==='종료')$('#controls').querySelectorAll('button').forEach(b=>b.disabled=!['reopen','buzzer'].includes(b.dataset.act))}
function teamControls(g,i){return `<div class="panel"><h3>${esc(i?g.b:g.a)}</h3><div class="buttons">${[1,2,...(g.mode==='5'?[3]:[])].map(n=>btn('+'+n,`score:${i}:${n}`,'scorebtn')).join('')}${btn('−1',`score:${i}:-1`)}</div><div class="buttons">${btn('파울 +',`foul:${i}:1`)}${btn('−',`foul:${i}:-1`)}</div><div class="buttons">${g.timeouts[i]>=timeoutLimit(g)?'<button disabled>타임아웃 소진</button>':btn('타임아웃',`timeout:${i}`)}${btn('횟수 −',`toMinus:${i}`)}</div></div>`}
function modal(html,fn){$('#formContent').innerHTML=html;modalSubmit=fn;$('#dialog').showModal()}
$('#cancel').onclick=()=>$('#dialog').close();$('#form').onsubmit=e=>{e.preventDefault();if(modalSubmit?.(new FormData(e.target))!==false)$('#dialog').close()};
function act(action,remote=false){if(display)return;unlock();let g=game();if(!g)return;const [kind,i,n]=action.split(':');if(kind==='buzzer'){beep('game');return}if(kind==='reset'||kind==='14')stopBuzzer('shot');if(kind==='timeout'&&g.timeouts[+i]>=timeoutLimit(g))return;if(kind==='reopen'){g.status='진행';persist();render();return}if(g.status==='종료')return;
if(kind==='editTime'){materialize(g);g.running=g.shotRunning=false;persist();render();modal(`<h2>계시 시간 수정</h2><label>남은 경기 시간 (초)<input name="clock" type="number" min="0" max="7200" step="0.1" value="${(g.clock/1000).toFixed(1)}" required></label><label>남은 샷클락 (초)<input name="shot" type="number" min="0" max="120" step="0.1" value="${g.shot/1000}" required></label>`,f=>mutate(g=>{g.clock=Number(f.get('clock'))*1000;g.shot=Number(f.get('shot'))*1000}));return}
if(kind==='undo'){const previous=g.history.pop();if(previous){const history=g.history;Object.assign(g,previous,{history,running:false,shotRunning:false,stamp:Date.now()});persist();render()}return}
if(kind==='finish'&&!confirm('경기를 종료하고 현재 결과를 저장할까요?'))return;
if(kind==='period'&&!remote&&!confirm('다음 쿼터/연장으로 이동할까요? 현재 쿼터 점수를 기록하고 팀파울을 초기화합니다.'))return;
mutate(g=>{switch(kind){case 'score':g.score[+i]=Math.max(0,g.score[+i]+Number(n));break;case 'foul':g.fouls[+i]=Math.max(0,g.fouls[+i]+Number(n));break;case 'toMinus':g.timeouts[+i]=Math.max(0,g.timeouts[+i]-1);g.timeoutLedger[timeoutGroup(g)]=[...g.timeouts];break;case 'timeout':g.timeouts[+i]++;g.timeoutLedger[timeoutGroup(g)]=[...g.timeouts];break;case 'toggle':if(g.timeoutEnd){delete g.timeoutEnd}g.running=!g.running&&(g.clock>0||(g.mode==='3'&&g.period>g.periods));if(g.running)g.status='진행';break;case 'shot':g.shotRunning=!g.shotRunning&&g.shot>0;if(g.shotRunning)g.status='진행';break;case 'adjust':g[i]=Math.max(0,g[i]+Number(n));if(g[i]===0){if(i==='clock')g.running=false;else g.shotRunning=false}break;case 'reset':case '14':g.shot=kind==='14'?14000:g.mode==='3'?12000:24000;g.shotRunning=false;break;case 'poss':g.pos=Number(i);break;case 'pos':g.pos=g.pos===1?2:1;break;case 'period':g.quarters.push({period:g.period,score:[...g.score]});g.period++;syncTimeouts(g);g.fouls=g.mode==='3'||g.period>g.periods?g.fouls:[0,0];g.clock=g.period>g.periods?(g.mode==='3'?0:g.otMinutes*60000):g.minutes*60000;g.shot=g.mode==='3'?12000:24000;g.running=g.shotRunning=false;delete g.timeoutEnd;break;case 'finish':g.status='종료';g.running=g.shotRunning=false;delete g.timeoutEnd;g.finishedAt=new Date().toISOString();break;}})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b&&!display)act(b.dataset.act);const s=e.target.closest('[data-game]');if(s&&!display){pause();db.game=s.dataset.game;persist();render()}});
function pause(){const g=game();if(g){materialize(g);g.running=g.shotRunning=false}persist()}
$('#tournaments').onchange=e=>{pause();db.selected=e.target.value;db.game=tour().games[0]?.id;persist();render()};
$('#newTournament').onclick=()=>modal('<h2>새 대회</h2><label>대회 이름<input name="name" maxlength="60" required placeholder="예: 2026 교내 농구대회"></label>',f=>{pause();const t={id:uid(),name:f.get('name').trim(),games:[]};if(!t.name)return false;db.tournaments.push(t);db.selected=t.id;db.game=null;persist();render()});
$('#addGame').onclick=()=>modal('<h2>경기 사전 등록</h2><p>한 줄에 한 경기씩 입력하세요. 여러 경기를 한 번에 등록할 수 있습니다.</p><label>홈팀, 원정팀<textarea name="matches" required placeholder="1학년 1반, 1학년 2반\nBLUE, WHITE"></textarea></label><label>경기 방식<select name="mode"><option value="5">5대5 · 10분 × 4쿼터</option><option value="3">3x3 · 10분 · 샷클락 12초</option></select></label>',f=>{const rows=f.get('matches').trim().split('\n').map(s=>s.split(',').map(x=>x.trim()));if(rows.some(r=>r.length!==2||r.some(v=>!v||v.length>40))){alert('각 줄을 팀 이름, 팀 이름 형식으로 입력해주세요. 팀 이름은 40자 이내입니다.');return false}for(const r of rows){const g=newGame(r[0],r[1],f.get('mode'));tour().games.push(g);db.game??=g.id}persist();render()});
$('#settings').onclick=()=>{const g=game();if(!g)return;modal(`<h2>경기 설정</h2><label>홈팀<input name="a" value="${esc(g.a)}" maxlength="40" required></label><label>원정팀<input name="b" value="${esc(g.b)}" maxlength="40" required></label><label>쿼터 시간 (분)<input name="minutes" type="number" min="1" max="60" value="${g.minutes}" required></label><label>쿼터 수<input name="periods" type="number" min="1" max="12" value="${g.periods}" required></label><label>연장 시간 (분)<input name="ot" type="number" min="1" max="30" value="${g.otMinutes}" required></label><p>진행 중 경기의 남은 시간은 ‘시간 수정’에서 변경합니다. 3x3 연장은 시간 제한 없이 점수를 수동으로 기록하고 종료하세요. 타임아웃은 전반 2회·후반 3회·연장마다 1회이며, 구간이 바뀌면 새로 부여됩니다. 3x3는 경기 전체 1회입니다.</p>`,f=>{if(g.status==='종료'){alert('결과 수정 재개 후 변경하세요.');return false}mutate(g=>{g.a=f.get('a').trim();g.b=f.get('b').trim();g.minutes=+f.get('minutes');g.periods=+f.get('periods');g.otMinutes=+f.get('ot');if(g.status==='대기')g.clock=g.minutes*60000})})};
$('#help').onclick=()=>modal('<h2>키보드 · 사용 안내</h2><p>공격시간: Q 14초 · W 24초 (3x3 12초) · E 시작/정지 · R +1초 · F −1초<br>경기시간: U +1분 · J −1분 · I +1초 · K −1초 · O 시작/정지<br>홈팀: A +1점 · S +2점 · D +3점 · Z −1점 · X 파울 +1 · C 타임아웃<br>원정팀: &quot; 키 +1점 · ; 키 +2점 · L +3점 · / 키 −1점 · . 키 파울 +1 · , 키 타임아웃<br>H: 누르는 동안 버저 · N: 다음 쿼터/연장<br>← / →: 공격권 지정<br>팀명 변경과 전체·경기시간 리셋 단축키는 사용하지 않습니다. 시간 증감은 진행/정지 상태를 유지하며 0 아래로 내려가지 않습니다. 타임아웃은 횟수만 바꿉니다.</p><p>단일 모니터: 전광판만 표시하며 오른쪽 아래 ⚙ 메뉴에서 설정·팀명·대회·저장 기능을 엽니다. 외부 모니터: 메인 화면에 모든 조작 메뉴를 펼쳐 표시합니다. 화면 모드는 메뉴 상단에서 선택합니다. 두 모드의 키보드 조작은 동일합니다.<br><br>PC 또는 iPad에 모니터를 유선으로 연결하고 확장 모드로 설정하세요. iPad/PC에는 점수판과 조작 버튼이 있는 종합 창을 유지하고, ‘외부 뷰어 열기’로 연 창만 확장 모니터로 옮기세요. 외부 뷰어는 전체·계시기·점수 중 선택한 정보만 표시하며 경기 조작은 받지 않습니다. 창 이동은 운영체제에서 직접 해야 합니다. 뷰어의 전체화면 버튼은 브라우저가 지원할 때 사용할 수 있습니다. 화면 잠금·기기 절전은 해제해주세요.</p><p>오프라인은 첫 접속 후 캐시 준비가 완료되어야 합니다. 브라우저 데이터 삭제 시 기록도 삭제되므로 백업을 권장합니다. 3x3의 21점 승리·연장 2점 선취는 운영자가 확인 후 종료합니다.</p>',()=>{});
document.addEventListener('keydown',e=>{if(display||$('#dialog').open||document.querySelector('#wirelessDialog')?.open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.repeat||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='KeyH'){e.preventDefault();beep('manual',null);return}const map={KeyQ:'14',KeyW:'reset',KeyE:'shot',KeyR:'adjust:shot:1000',KeyF:'adjust:shot:-1000',KeyU:'adjust:clock:60000',KeyJ:'adjust:clock:-60000',KeyI:'adjust:clock:1000',KeyK:'adjust:clock:-1000',KeyO:'toggle',KeyA:'score:0:1',KeyS:'score:0:2',KeyD:'score:0:3',KeyZ:'score:0:-1',KeyX:'foul:0:1',KeyC:'timeout:0',Quote:'score:1:1',Semicolon:'score:1:2',KeyL:'score:1:3',Slash:'score:1:-1',Period:'foul:1:1',Comma:'timeout:1',KeyN:'period'};if((e.code==='KeyQ'||['KeyD','KeyL'].includes(e.code))&&game()?.mode==='3')return;if(map[e.code]){e.preventDefault();act(map[e.code])}if(['ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();mutate(g=>g.pos=e.code==='ArrowLeft'?1:2)}});
$('#display').onclick=()=>{screenMode='dual';menuOpen=false;try{localStorage.setItem('courtboard-screen-mode','dual')}catch{}applyScreenMode();persist();const w=window.open(`?display=${$('#view').value}`,'courtboard-'+$('#view').value,'popup,width=1280,height=720');if(!w)alert('표시 창을 열려면 이 사이트의 팝업을 허용해주세요.')};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='courtboard-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onclick=()=>$('#file').click();
$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error();const data=JSON.parse(await f.text());if(!Array.isArray(data.tournaments)||!data.tournaments.length||data.tournaments.some(t=>typeof t.name!=='string'||!Array.isArray(t.games)||t.games.some(g=>!['3','5'].includes(g.mode)||typeof g.a!=='string'||typeof g.b!=='string'||!['score','fouls','timeouts'].every(k=>Array.isArray(g[k])&&g[k].length===2&&g[k].every(n=>Number.isFinite(n)&&n>=0))||!['clock','shot','minutes','period','periods','otMinutes'].every(k=>Number.isFinite(g[k])&&g[k]>=0))))throw Error();if(!confirm('백업을 복원하면 현재 기기의 전체 대회 목록을 교체합니다. 계속할까요?'))return;data.tournaments.forEach(t=>{t.id=uid();t.games.forEach(g=>{g.id=uid();g.running=g.shotRunning=false;g.stamp=Date.now();g.history=[];delete g.timeoutLedger;delete g.timeoutGroup;syncTimeouts(g);delete g.timeoutEnd})});data.selected=data.tournaments[0].id;data.game=data.tournaments[0].games[0]?.id;db=data;persist();render()}catch{alert('유효한 COURTBOARD 백업 파일을 선택해주세요.')}finally{e.target.value=''}};
if(display){document.body.className='display '+(display==='clock'?'onlyclock':display==='score'?'onlyscore':'');const b=document.createElement('button');b.className='fullscreen';b.textContent='⛶ 전체화면';b.onclick=()=>document.documentElement.requestFullscreen?.();document.body.append(b);channel&&(channel.onmessage=e=>{db=e.data;render()});window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){db=JSON.parse(e.newValue);render()}})}else{for(const t of db.tournaments)for(const g of t.games){materialize(g);g.running=g.shotRunning=false;g.history??=[];syncTimeouts(g);delete g.timeoutEnd}persist()}
function tick(){const g=game();if(!g)return;if(!display&&((g.running&&!(g.mode==='3'&&g.period>g.periods)&&remaining(g,'clock')===0)||(g.shotRunning&&remaining(g,'shot')===0))){materialize(g);const gameExpired=g.running&&!(g.mode==='3'&&g.period>g.periods)&&g.clock===0;const shotExpired=g.shotRunning&&g.shot===0;if(gameExpired){g.running=false;beep('game')}if(shotExpired){g.shotRunning=false;beep('shot')}persist();render()}board()}
setInterval(tick,50);
applyScreenMode();render();if('serviceWorker'in navigator&&!display)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('#saveState').textContent='● 오프라인 준비 완료'}).catch(()=>{$('#saveState').textContent='● 기기 저장 · 오프라인 미준비'});
